1#HN:import { test, expect } from '@playwright/test';
2#QJ:import * as fs from 'fs';
3#MZ:import * as path from 'path';
4#HP:import { fileURLToPath } from 'url';
5#BT:
6#JQ:const __dirname = path.dirname(fileURLToPath(import.meta.url));
7#QT:const BLINK_PATH = path.resolve(__dirname, '../../examples/blink.cypcb');
8#XW:
9#HY:/** Load blink.cypcb via the app's __loadBoard debug surface. */
10#PK:async function loadBlink(page: import('@playwright/test').Page): Promise<void> {
11#WS:  const content = fs.readFileSync(BLINK_PATH, 'utf-8');
12#QV:  await page.evaluate((src) => {
13#WY:    const loader = (window as any).__loadBoard;
14#QM:    if (loader) loader(src);
15#JJ:  }, content);
16#VJ:  await page.waitForTimeout(500);
17#SH:}
18#KS:
19#YV:/** Activate 3D view and wait for renderer to be ready. */
20#TR:async function activate3D(page: import('@playwright/test').Page): Promise<void> {
21#XT:  await page.click('#view-3d-btn');
22#JR:  await expect(page.locator('#view-3d-btn')).toHaveClass(/active/, { timeout: 5_000 });
23#HT:  // Wait for renderer to finish building geometry
24#PT:  await page.waitForFunction(
25#BB:    () => (window as any).__renderer3d?.isActive === true,
26#SQ:    { timeout: 5_000 },
27#NH:  );
28#WV:  // Allow build methods to complete
29#ZZ:  await page.waitForTimeout(300);
30#RZ:}
31#SZ:
32#KV:/** Read all geometry counters from the debug surface. */
33#JP:async function getGeometryCounts(page: import('@playwright/test').Page) {
34#VN:  return page.evaluate(() => {
35#VK:    const r = (window as any).__renderer3d;
36#YS:    return {
37#YS:      componentCount: r?.componentCount,
38#TQ:      traceSegmentCount: r?.traceSegmentCount,
39#XV:      padCount: r?.padCount,
40#SN:      viaCount: r?.viaCount,
41#WT:      meshCount: r?.meshCount,
42#KN:    };
43#XW:  });
44#KR:}
