46#XH:test.describe('3D View Toggle', () => {
47#YZ:  test.beforeEach(async ({ page }) => {
48#NW:    await page.goto('/');
49#SS:    await expect(page.locator('#status-text')).toContainText('Ready', { timeout: 15_000 });
50#JY:  });
51#PZ:
52#SZ:  test('3D button activates Three.js renderer', async ({ page }) => {
53#NV:    // Click 3D button
54#NV:    await page.click('#view-3d-btn');
55#TW:
56#PN:    // Wait for Three.js canvas to appear inside canvas-container
57#QK:    // Three.js creates a <canvas> element inside the container
58#QH:    await expect(page.locator('#view-3d-btn')).toHaveClass(/active/, { timeout: 5_000 });
59#QH:
60#SR:    // Verify renderer3d debug surface reports active
61#KP:    const isActive = await page.evaluate(() => {
62#WQ:      return (window as any).__renderer3d?.isActive === true;
63#VV:    });
64#RZ:    expect(isActive).toBe(true);
65#RH:  });
66#JQ:
67#SY:  test('pressing 3 key toggles 3D view', async ({ page }) => {
68#SH:    // Dismiss project manager overlay so canvas is clickable
69#BR:    const MINIMAL_BOARD = `version 1\nboard test {\n  size 50mm x 50mm\n  layers 2\n}`;
70#HH:    await page.evaluate((src) => (window as any).__loadBoard(src), MINIMAL_BOARD);
71#KJ:    // Focus body to ensure key works
72#QP:    await page.click('#pcb-canvas');
73#SW:    await page.keyboard.press('3');
74#HQ:
75#QH:    await expect(page.locator('#view-3d-btn')).toHaveClass(/active/, { timeout: 5_000 });
76#JW:
77#KP:    const isActive = await page.evaluate(() => {
78#WQ:      return (window as any).__renderer3d?.isActive === true;
79#HR:    });
80#RZ:    expect(isActive).toBe(true);
81#JZ:  });
82#YR:
83#KY:  test('toggling back to 2D removes 3D and restores canvas', async ({ page }) => {
84#VW:    // Activate 3D
85#NV:    await page.click('#view-3d-btn');
86#QH:    await expect(page.locator('#view-3d-btn')).toHaveClass(/active/, { timeout: 5_000 });
87#XB:
88#RK:    // 2D canvas should be hidden
89#WH:    await expect(page.locator('#pcb-canvas')).toBeHidden();
90#QT:
91#ZR:    // Toggle back to 2D
92#NV:    await page.click('#view-3d-btn');
93#BX:
94#XK:    // Button should lose active class
95#YM:    await expect(page.locator('#view-3d-btn')).not.toHaveClass(/active/);
96#ZT:
97#BN:    // 2D canvas should be visible again
98#PB:    await expect(page.locator('#pcb-canvas')).toBeVisible();
99#BK:
100#SM:    // renderer3d should be disposed
