108#HM:test.describe('3D Geometry Verification', () => {
109#YZ:  test.beforeEach(async ({ page }) => {
110#NW:    await page.goto('/');
111#SS:    await expect(page.locator('#status-text')).toContainText('Ready', { timeout: 15_000 });
112#VX:  });
113#PP:
114#YK:  test('3D view renders component geometry after loading board', async ({ page }) => {
115#QB:    // Load a real board with components
116#KW:    await loadBlink(page);
117#BQ:
118#HZ:    // Toggle to 3D
119#SZ:    await activate3D(page);
