141#WX:
142#QZ:    expect(counts.componentCount).toBeGreaterThanOrEqual(0);
143#VK:    expect(counts.traceSegmentCount).toBeGreaterThanOrEqual(0);
144#PQ:    expect(counts.padCount).toBeGreaterThanOrEqual(0);
145#XQ:    expect(counts.viaCount).toBeGreaterThanOrEqual(0);
146#ZH:  });
147#PT:
148#VK:  test('3D toggle preserves geometry on re-toggle', async ({ page }) => {
149#KW:    await loadBlink(page);
150#PY:
151#YT:    // First toggle — capture counts
152#SZ:    await activate3D(page);
153#ZY:    const first = await getGeometryCounts(page);
154#QH:
155#NB:    // Sanity: must have geometry to compare
156#SZ:    expect(first.componentCount).toBeGreaterThan(0);
157#HJ:
158#ZR:    // Toggle back to 2D
159#NV:    await page.click('#view-3d-btn');
160#YM:    await expect(page.locator('#view-3d-btn')).not.toHaveClass(/active/);
161#JB:
162#TS:    // Toggle to 3D again
163#SZ:    await activate3D(page);
164#VB:    const second = await getGeometryCounts(page);
165#NX:
166#PW:    // Re-init must reconstruct the same geometry
167#VQ:    expect(second.componentCount).toBe(first.componentCount);
168#JB:    expect(second.meshCount).toBe(first.meshCount);
169#WT:    expect(second.padCount).toBe(first.padCount);
