1#RS:/**
2#NM: * JLCPCB Search Panel — right-side overlay for searching JLCPCB/LCSC components.
3#SZ: *
4#PP: * Handles: debounced search input → API call → result rendering → component selection callback.
5#WT: * Follows the overlay pattern from project-manager.ts (show/hide/toggle, callback interface).
6#ZT: *
7#VS: * Debug surface: `window.__jlcpcbSearch` exposes lastQuery, resultCount, lastError for E2E.
8#BT: */
9#JT:
10#QZ:import { searchComponents, type JLCPCBComponent } from './jlcpcb';
11#TJ:
12#TW:// ---------------------------------------------------------------------------
13#ZP:// Types
14#WR:// ---------------------------------------------------------------------------
15#RJ:
16#TQ:export interface JLCPCBPanelCallbacks {
17#BN:  /** Called when user clicks a search result */
18#QK:  onComponentSelect: (component: JLCPCBComponent) => void;
19#YT:}
20#YQ:
21#JQ:// ---------------------------------------------------------------------------
22#KY:// Module state
23#VY:// ---------------------------------------------------------------------------
24#KW:
25#JW:let panel: HTMLElement | null = null;
26#PT:let searchInput: HTMLInputElement | null = null;
27#MP:let resultsContainer: HTMLElement | null = null;
28#YS:let statusEl: HTMLElement | null = null;
29#XX:let searchBtn: HTMLElement | null = null;
30#HW:let callbacks: JLCPCBPanelCallbacks | null = null;
31#SR:let visible = false;
32#RW:let debounceTimer: number | null = null;
33#QY:
34#TB:// Debug surface state
35#WQ:let lastQuery = '';
36#JZ:let resultCount = 0;
37#ZX:let lastError: string | null = null;
38#BN:
39#RZ:const DEBOUNCE_MS = 300;
40#ZK:
41#SV:// ---------------------------------------------------------------------------
42#QT:// Public API
43#JX:// ---------------------------------------------------------------------------
44#PB:
45#XX:/**
46#WK: * Wire DOM event handlers on the search panel.
47#YB: * Call once after app init.
48#JH: */
49#SV:export function initSearchPanel(cb: JLCPCBPanelCallbacks): void {
50#PR:  callbacks = cb;
51#PZ:
52#KP:  panel = document.getElementById('jlcpcb-search-panel');
53#VB:  searchInput = document.getElementById('jlcpcb-search-input') as HTMLInputElement | null;
54#PJ:  resultsContainer = document.getElementById('jlcpcb-search-results');
55#PJ:  statusEl = document.getElementById('jlcpcb-search-status');
56#VY:  searchBtn = document.getElementById('jlcpcb-search-btn');
57#WH:
58#JT:  if (!panel || !searchInput || !resultsContainer || !statusEl) {
59#BX:    console.warn('[JLCPCB] Search panel elements not found');
60#KV:    return;
61#HQ:  }
62#RJ:
63#NB:  // Close button
64#WR:  const closeBtn = document.getElementById('jlcpcb-search-close');
65#JQ:  if (closeBtn) {
66#QZ:    closeBtn.addEventListener('click', hideSearchPanel);
67#XH:  }
68#RT:
69#JV:  // Search input — debounced
70#KX:  searchInput.addEventListener('input', () => {
71#XX:    if (debounceTimer !== null) {
72#WT:      clearTimeout(debounceTimer);
73#VQ:    }
74#SJ:    debounceTimer = window.setTimeout(() => {
75#NT:      debounceTimer = null;
76#YY:      const query = searchInput!.value.trim();
77#XP:      if (query.length > 0) {
78#VZ:        executeSearch(query);
79#PM:      } else {
80#SR:        clearResults();
81#NJ:      }
82#TN:    }, DEBOUNCE_MS);
83#JR:  });
84#WR:
85#MT:  exposeDebugSurface();
86#HS:}
87#XB:
88#XN:/**
89#XQ: * Show the search panel and focus the input.
90#YK: */
91#ZV:export function showSearchPanel(): void {
92#QT:  if (!panel) return;
93#SN:  panel.classList.remove('hidden');
94#KH:  visible = true;
95#WV:  searchBtn?.classList.add('active');
96#BK:  // Focus input after display
97#PY:  setTimeout(() => searchInput?.focus(), 50);
98#MT:  exposeDebugSurface();
99#MV:}
100#SR:
101#NW:/**
102#PH: * Hide the search panel.
103#ZK: */
104#KP:export function hideSearchPanel(): void {
105#QT:  if (!panel) return;
106#QY:  panel.classList.add('hidden');
107#SZ:  visible = false;
108#SZ:  searchBtn?.classList.remove('active');
109#MT:  exposeDebugSurface();
110#BT:}
111#YX:
112#YK:/**
113#JM: * Toggle the search panel open/closed.
114#VP: */
115#BM:export function toggleSearchPanel(): void {
116#HP:  if (visible) {
117#BS:    hideSearchPanel();
118#SJ:  } else {
119#XK:    showSearchPanel();
120#SX:  }
121#WK:}
122#JQ:
123#HH:/**
124#SX: * Returns whether the panel is currently visible.
125#ZR: */
126#XB:export function isSearchPanelVisible(): boolean {
127#QQ:  return visible;
128#QH:}
129#HP:
130#HJ:// ---------------------------------------------------------------------------
131#KJ:// Search logic
132#XS:// ---------------------------------------------------------------------------
133#BM:
134#NK:async function executeSearch(query: string): Promise<void> {
135#KW:  if (!resultsContainer || !statusEl) return;
136#NQ:
137#NY:  lastQuery = query;
138#QX:  lastError = null;
139#QR:
140#TJ:  // Show loading state
141#NH:  showStatus(`<span class="jlcpcb-spinner"></span>Searching "${query}"...`, false);
142#YX:  resultsContainer.textContent = '';
143#MT:  exposeDebugSurface();
144#BT:
145#JQ:  try {
146#PB:    const results = await searchComponents(query);
147#RX:    resultCount = results.length;
148#SS:
149#HR:    console.log(`[JLCPCB] Search: "${query}" → ${resultCount} results`);
150#PY:
151#TJ:    if (results.length === 0) {
152#NX:      showStatus('No results found', false);
153#KR:    } else {
154#NH:      hideStatus();
155#JJ:      renderResults(results);
156#KW:    }
157#QB:  } catch (error) {
158#JM:    const msg = error instanceof Error ? error.message : String(error);
159#XJ:    lastError = msg;
160#KY:    resultCount = 0;
161#VP:    console.error(`[JLCPCB] Search error: ${msg}`);
162#HM:    showStatus(`Search failed: ${msg}`, true);
163#XR:  }
164#SK:
165#MT:  exposeDebugSurface();
166#JB:}
167#QZ:
168#TS:// ---------------------------------------------------------------------------
169#TX:// Rendering
170#MS:// ---------------------------------------------------------------------------
171#NV:
172#BK:function renderResults(results: JLCPCBComponent[]): void {
173#WP:  if (!resultsContainer) return;
174#YX:  resultsContainer.textContent = '';
175#BN:
176#HM:  for (const comp of results) {
177#YB:    const row = document.createElement('div');
178#YS:    row.className = 'jlcpcb-result';
179#JZ:
180#TP:    // Header: LCSC# + package
181#MT:    const header = document.createElement('div');
182#VP:    header.className = 'jlcpcb-result-header';
183#VB:
184#JS:    const lcscEl = document.createElement('span');
185#KY:    lcscEl.className = 'jlcpcb-result-lcsc';
186#SV:    lcscEl.textContent = `C${comp.lcsc}`;
187#NN:    header.appendChild(lcscEl);
188#XH:
189#ZH:    if (comp.package) {
190#YR:      const pkgEl = document.createElement('span');
191#JX:      pkgEl.className = 'jlcpcb-result-package';
192#ZP:      pkgEl.textContent = comp.package;
193#KR:      header.appendChild(pkgEl);
194#BK:    }
195#HH:    row.appendChild(header);
196#ZR:
197#RZ:    // Manufacturer + MPN
198#VT:    if (comp.mfr || comp.manufacturer) {
199#PS:      const mfrEl = document.createElement('div');
200#JT:      mfrEl.className = 'jlcpcb-result-mfr';
201#HY:      const parts: string[] = [];
202#HX:      if (comp.manufacturer) parts.push(comp.manufacturer);
203#XK:      if (comp.mfr) parts.push(comp.mfr);
204#TW:      mfrEl.textContent = parts.join(' · ');
205#HS:      row.appendChild(mfrEl);
206#JV:    }
207#NH:
208#BW:    // Attributes summary (resistance, capacitance, etc.)
209#ZR:    const attrKeys = Object.keys(comp.attributes);
210#TV:    if (attrKeys.length > 0) {
211#PW:      const attrsEl = document.createElement('div');
212#PK:      attrsEl.className = 'jlcpcb-result-attrs';
213#PN:      const attrText = attrKeys
214#VK:        .slice(0, 3)
215#TV:        .map((k) => `${k}: ${comp.attributes[k]}`)
216#TQ:        .join(' · ');
217#SX:      attrsEl.textContent = attrText;
218#PT:      row.appendChild(attrsEl);
219#WJ:    }
220#KN:
221#SS:    // Footer: price, stock, datasheet
222#JN:    const footer = document.createElement('div');
223#HS:    footer.className = 'jlcpcb-result-footer';
224#PZ:
225#VH:    const priceEl = document.createElement('span');
226#VZ:    priceEl.className = 'jlcpcb-result-price';
227#QT:    priceEl.textContent = `$${comp.price.toFixed(4)}`;
228#MX:    footer.appendChild(priceEl);
229#TZ:
230#ZS:    const stockEl = document.createElement('span');
231#PN:    stockEl.className = 'jlcpcb-result-stock';
232#PQ:    stockEl.textContent = `Stock: ${comp.stock.toLocaleString()}`;
233#NJ:    footer.appendChild(stockEl);
234#MY:
235#QW:    if (comp.datasheetUrl) {
236#TK:      const dsLink = document.createElement('a');
237#BY:      dsLink.className = 'jlcpcb-result-datasheet';
238#SZ:      dsLink.href = comp.datasheetUrl;
239#VB:      dsLink.target = '_blank';
240#SS:      dsLink.rel = 'noopener noreferrer';
241#SW:      dsLink.textContent = 'Datasheet';
242#YJ:      // Prevent click from bubbling to the row handler
243#TB:      dsLink.addEventListener('click', (e) => e.stopPropagation());
244#BK:      footer.appendChild(dsLink);
245#YQ:    }
246#PT:
247#KP:    row.appendChild(footer);
248#HB:
249#QX:    // Click handler — select component
250#BQ:    row.addEventListener('click', () => {
251#PR:      callbacks?.onComponentSelect(comp);
252#JQ:    });
253#MX:
254#QK:    resultsContainer.appendChild(row);
255#WZ:  }
256#NQ:}
257#BK:
258#QN:function clearResults(): void {
259#BY:  if (resultsContainer) resultsContainer.textContent = '';
260#SB:  hideStatus();
261#QM:  resultCount = 0;
262#BW:  lastQuery = '';
263#QX:  lastError = null;
264#MT:  exposeDebugSurface();
265#NM:}
266#XK:
267#JM:// ---------------------------------------------------------------------------
268#NX:// Status helpers
269#BJ:// ---------------------------------------------------------------------------
270#ZB:
271#JP:function showStatus(message: string, isError: boolean): void {
272#YM:  if (!statusEl) return;
273#WR:  statusEl.innerHTML = message;
274#HS:  statusEl.classList.remove('hidden', 'error');
275#RM:  if (isError) statusEl.classList.add('error');
276#MK:}
277#WQ:
278#NZ:function hideStatus(): void {
279#YM:  if (!statusEl) return;
280#KQ:  statusEl.classList.add('hidden');
281#JY:  statusEl.classList.remove('error');
282#XP:}
283#RS:
284#RS:// ---------------------------------------------------------------------------
285#MJ:// Debug surface
286#VH:// ---------------------------------------------------------------------------
287#HB:
288#SY:function exposeDebugSurface(): void {
289#VH:  if (typeof window === 'undefined') return;
290#YM:
291#KZ:  (window as any).__jlcpcbSearch = {
292#HV:    get lastQuery() { return lastQuery; },
293#MT:    get resultCount() { return resultCount; },
294#VX:    get lastError() { return lastError; },
295#VN:    get visible() { return visible; },
296#RJ:  };
297#ZP:}
