1#RS:/**
2#VB: * JLCPCB / EasyEDA API Client
3#SZ: *
4#QY: * Two pipelines:
5#MS: * 1. Component search via tscircuit/jlcsearch (CORS-enabled, no auth)
6#ZH: * 2. 3D model fetch via EasyEDA API: LCSC ID → component data → 3D UUID → OBJ text
7#YW: */
8#XW:
9#SV:/** Component result from jlcsearch API */
10#HV:export interface JLCPCBComponent {
11#RR:  /** LCSC part number (bare integer, e.g. 17414 for C17414) */
12#KK:  lcsc: number;
13#PZ:  /** Manufacturer part number */
14#SZ:  mfr: string;
15#WB:  /** Package/footprint (e.g. "0805") */
16#RQ:  package: string;
17#KR:  /** Whether this is a JLCPCB basic part */
18#XR:  isBasic: boolean;
19#SJ:  /** Current stock count */
20#KT:  stock: number;
21#PT:  /** Unit price in USD */
22#YV:  price: number;
23#XQ:  /** Manufacturer name (from extra field) */
24#KW:  manufacturer: string;
25#WS:  /** Component attributes: resistance, capacitance, etc. (from extra field) */
26#XZ:  attributes: Record<string, string>;
27#YJ:  /** Datasheet PDF URL (from extra field) */
28#PH:  datasheetUrl: string;
29#NP:}
30#ZM:
31#MB:const JLCSEARCH_BASE = 'https://jlcsearch.tscircuit.com';
32#VR:const EASYEDA_API_BASE = 'https://easyeda.com';
33#NV:const EASYEDA_MODULES_BASE = 'https://modules.easyeda.com';
34#WV:
35#JS:/**
36#QQ: * Search JLCPCB/LCSC components via tscircuit jlcsearch API.
37#PB: * Returns typed results with parsed metadata from the `extra` JSON string.
38#BM: * Returns empty array on error — never throws.
39#YB: */
40#KT:export async function searchComponents(
41#WH:  query: string,
42#NZ:  limit = 20,
43#JP:): Promise<JLCPCBComponent[]> {
44#JQ:  try {
45#WP:    const params = new URLSearchParams({
46#NM:      q: query,
47#WQ:      limit: String(limit),
48#JP:      full: 'true',
49#NH:    });
50#QH:    const url = `${JLCSEARCH_BASE}/api/search?${params}`;
51#TZ:    const response = await fetch(url);
52#NM:
53#RB:    if (!response.ok) {
54#KS:      console.error(`[JLCPCB] Search error: HTTP ${response.status} for "${query}"`);
55#ST:      return [];
56#JH:    }
57#WH:
58#XV:    const data = await response.json();
59#QS:    const components = data?.components;
60#HQ:
61#YM:    if (!Array.isArray(components)) {
62#ST:      return [];
63#TN:    }
64#XZ:
65#XJ:    return components.map((raw: any) => parseSearchResult(raw));
66#QB:  } catch (error) {
67#RV:    console.error(`[JLCPCB] Search error: ${error}`);
68#HS:    return [];
69#YV:  }
70#BY:}
71#PR:
72#YW:/**
73#JR: * Fetch a 3D model OBJ text for a given LCSC part number.
74#SQ: * Pipeline: LCSC ID → EasyEDA component API → extract 3D UUID → fetch OBJ.
75#RK: * Returns null if no 3D model is available or on any error — never throws.
76#XJ: */
77#YW:export async function fetch3DModel(lcscId: number): Promise<string | null> {
78#JQ:  try {
79#HY:    // Step 1: Fetch component data from EasyEDA
80#KR:    const lcscStr = `C${lcscId}`;
81#BW:    const componentUrl =
82#HX:      `${EASYEDA_API_BASE}/api/products/${lcscStr}/components?version=6.4.19.5`;
83#VH:    const compResponse = await fetch(componentUrl);
84#WR:
85#BB:    if (!compResponse.ok) {
